create or replace function public.delete_savings_goal(
  p_goal_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can manage goals.' using errcode = '42501';
